  ('FW70','FACTUURWACHT','precies 11 policies op de 4 tabellen, geen ALL meer, allemaal voor authenticated','postgres','check','select (select count(*) from pg_policies where schemaname = ''public'' and tablename in (''invoices'',''invoice_lines'',''payments'',''documents'')) = 11 and not exists (select 1 from pg_policies where schemaname = ''public'' and tablename in (''invoices'',''invoice_lines'',''payments'',''documents'') and (cmd = ''ALL'' or roles <> ''{authenticated}''))',false,true,10,'',null,null),
  ('FW71','FACTUURWACHT','geen enkele wis-policy op facturen en betalingen, geen wijzig-policy op betalingen','postgres','check','select not exists (select 1 from pg_policies where schemaname = ''public'' and ((tablename in (''invoices'',''payments'',''documents'') and cmd in (''DELETE'',''ALL'')) or (tablename in (''payments'',''documents'') and cmd in (''UPDATE'',''ALL''))))',false,true,10,'',null,null),
  ('FW72','FACTUURWACHT','wachtfuncties: DEFINER, search_path vast, voor niemand uitvoerbaar','postgres','check','select count(*) = 2 from pg_proc where pronamespace = ''public''::regnamespace and proname in (''invoices_guard'',''invoice_child_guard'') and prosecdef and proconfig = ''{"search_path=public, pg_temp"}'' and proowner = ''postgres''::regrole and not has_function_privilege(''anon'', oid, ''EXECUTE'') and not has_function_privilege(''authenticated'', oid, ''EXECUTE'') and not has_function_privilege(''service_role'', oid, ''EXECUTE'')',false,true,10,'',null,null),
  ('FW73','FACTUURWACHT','3 wachttriggers op de juiste tabellen en bewerkingen','postgres','check','select coalesce(string_agg(tgrelid::regclass::text || '':'' || tgtype, '','' order by tgrelid::regclass::text) = ''invoice_lines:31,invoices:31,payments:7'', false) from pg_trigger where tgname in (''invoices_guard'',''invoice_child_guard'')',false,true,10,'',null,null),
  ('FW74','FACTUURWACHT','module_wacht en alle bestaande trigger-functies ongewijzigd (vingerafdruk van 0030)','postgres','check','select md5(btrim(regexp_replace((select prosrc from pg_proc where proname = ''module_wacht''), ''\s+'', '' '', ''g''))) = ''1ae0dbb059cec09d9fde20aad42c9a3f'' and (select md5(string_agg(p.proname || md5(p.prosrc), ''|'' order by p.proname)) from pg_proc p where p.pronamespace = ''public''::regnamespace and p.prorettype = ''trigger''::regtype and p.proname not in (''module_wacht'',''invoices_guard'',''invoice_child_guard'') and p.proname not like ''%pin\_wacht'') = ''29c836f2b151411df746182866d2a985''',true,true,0,'',null,null),
  ('FW80','FACTUURWACHT','betalingen uit: administratie zet sent -> paid: geweigerd door de module (niet door de factuurwacht)','a.admin@staging.test','check','select hardening_test.refused_with($$update invoices set status = ''paid'' where id = ''a0000000-0000-0000-0000-000000000501''$$, ''staat uit'')',true,true,0,'','insert into restaurant_features values (''a0000000-0000-0000-0000-000000000001'',''payment_registration'',false,now());',null),
  ('FW81','FACTUURWACHT','betalingen uit: paid -> sent: geweigerd door de factuurwacht (module raakt dit niet)','service_role','check','select hardening_test.refused_with($$update invoices set status = ''sent'' where id = ''a0000000-0000-0000-0000-000000000502''$$, ''Ongeldige factuurstatus'')',false,true,10,'','insert into restaurant_features values (''a0000000-0000-0000-0000-000000000001'',''payment_registration'',false,now());',null),
