  ('OR01','RECHTEN13','lint: elk tabelrecht van authenticated heeft een policy voor die bewerking, en elke policy een recht','postgres','check','select not exists (select 1 from pg_class c, unnest(''{SELECT,INSERT,UPDATE,DELETE}''::text[]) o where c.relnamespace = ''public''::regnamespace and c.relkind = ''r'' and c.relname not like ''\_%'' and (case o when ''DELETE'' then has_table_privilege(''authenticated'', c.oid, o) else has_any_column_privilege(''authenticated'', c.oid, o) end) <> exists (select 1 from pg_policies p where p.schemaname = ''public'' and p.tablename = c.relname and p.cmd in (o, ''ALL'') and p.roles && ''{authenticated,public}''))',false,true,13,'',null,null),
  ('OR02','RECHTEN13','RLS staat aan op elke tabel in public','postgres','check','select not exists (select 1 from pg_class c where c.relnamespace = ''public''::regnamespace and c.relkind = ''r'' and c.relname not like ''\_%'' and not c.relrowsecurity)',true,true,0,'',null,null),
  ('OR03','RECHTEN13','bewust dichte tabellen: authenticated heeft er geen enkel recht','postgres','check','select not exists (select 1 from pg_class c where c.relnamespace = ''public''::regnamespace and c.relname in (''contacts'',''integration_plugins'',''notifications'',''email_settings'',''features'',''restaurant_features'',''platform_admins'',''platform_log'') and has_table_privilege(''authenticated'', c.oid, ''select,insert,update,delete,truncate,references,trigger''))',false,true,13,'',null,null),
  ('OR04','RECHTEN13','authenticated heeft geen recht op platform_log_id_seq','postgres','check','select not has_sequence_privilege(''authenticated'', ''public.platform_log_id_seq'', ''usage,select,update'')',false,true,13,'',null,null),
  ('OR05','RECHTEN13','geen MAINTAIN voor anon en authenticated op tabellen in public','postgres','check','select not exists (select 1 from pg_class c, aclexplode(c.relacl) x where c.relnamespace = ''public''::regnamespace and x.grantee::regrole::text in (''anon'',''authenticated'') and x.privilege_type = ''MAINTAIN'')',false,true,13,'',null,'current_setting(''server_version_num'')::int >= 170000'),
  ('OR06','RECHTEN13','standaardrechten van postgres voor nieuwe tabellen: geen MAINTAIN voor anon en authenticated','postgres','check','select not exists (select 1 from pg_default_acl d, aclexplode(d.defaclacl) x where d.defaclrole = ''postgres''::regrole and d.defaclnamespace in (0, ''public''::regnamespace) and d.defaclobjtype = ''r'' and x.grantee::regrole::text in (''anon'',''authenticated'') and x.privilege_type = ''MAINTAIN'')',false,true,13,'',null,'current_setting(''server_version_num'')::int >= 170000'),
